package com.manishrawat.realestate.model;
public abstract class User { protected int id; protected String name,email,password,role,phone; protected User(int id,String name,String email,String password,String role,String phone){this.id=id;this.name=name;this.email=email;this.password=password;this.role=role;this.phone=phone;} public abstract String getDashboard(); public int getId(){return id;} public String getName(){return name;} public String getEmail(){return email;} public String getPassword(){return password;} public String getRole(){return role;} public String getPhone(){return phone;} }
